plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.wails.{{.Name}}
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
NSLocationUsageDescription
Meridian uses your location only so macOS will reveal nearby Wi-Fi network names (SSIDs) in the Wi-Fi analyzer. Your location is never stored, logged or sent anywhere.
NSLocationWhenInUseUsageDescription
Meridian uses your location only so macOS will reveal nearby Wi-Fi network names (SSIDs) in the Wi-Fi analyzer. Your location is never stored, logged or sent anywhere.
NSLocalNetworkUsageDescription
Meridian needs local network access to reach the devices you point its tools at — printers, routers, switches and other hosts on your LAN (ping, port and printer checks, ARP/mDNS discovery, SNMP). Without it macOS silently blocks those tools. Nothing is stored or sent anywhere.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
